using System;

namespace StdbModule;

public static partial class ItalianQuotes
{
    public static class CesarePavese
    {
        public static readonly Quote[] Quotes = new Quote[]
        {
            new Quote { Id = "https://it.wikiquote.org/wiki/Cesare_Pavese", Text = "avere una tradizione è meno che nulla, è soltanto cercandola che si può viverla.", Author = "Cesare Pavese" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Cesare_Pavese", Text = "Lo sai questo? [...] Per te la morte è una cosa che accade, come il giorno e la notte. Tu sei uno di noi, Issione. Tu sei tutto nel gesto che fai. Ma per loro, gli immortali, i tuoi gesti hanno un senso che si prolunga.", Author = "Cesare Pavese" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Cesare_Pavese", Text = "Quassù la legge non arriva, Nefele. Qui la legge è il nevaio, la bufera, la tenebra. E quando viene il giorno chiaro e tu ti accosti leggera alla rupe, è troppo bello per pensarci ancora.", Author = "Cesare Pavese" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Cesare_Pavese", Text = "Nessuno si uccide. La morte è destino. Non si può che augurarsela, Ippòloco.", Author = "Cesare Pavese" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Cesare_Pavese", Text = "Che degli dèi si parla troppo. Esser cieco non è una disgrazia diversa da esser vivo.", Author = "Cesare Pavese" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Cesare_Pavese", Text = "Ma gli dèi possono dar fastidio, accostare o scostare le cose. Non toccarle, non mutarle. Sono venuti troppo tardi.", Author = "Cesare Pavese" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Cesare_Pavese", Text = "Nient'affatto. Non ci sono cose vili se non per gli dèi.", Author = "Cesare Pavese" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Cesare_Pavese", Text = "Che per nascere occorra morire, lo sanno anche gli uomini. Non lo sanno gli olimpici. Se lo sono scordato.", Author = "Cesare Pavese" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Cesare_Pavese", Text = "Il desiderio non è canto. Il desiderio schianta e brucia, come il serpe, come il vento.", Author = "Cesare Pavese" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Cesare_Pavese", Text = "Non so. Ma ho sentito narrare di libere vite di là dai monti e dai fiumi, di traversate, di arcipelaghi, d'incontri con mostri e con dèi.", Author = "Cesare Pavese" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Cesare_Pavese", Text = "Avevano tutti una madre, Meleagro. E fatiche da compiere. E una morte li attendeva, per la passione di qualcuno.", Author = "Cesare Pavese" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Cesare_Pavese", Text = "Vorrei che fossero più atroci ancora. Vorrei essere l'uomo più sozzo e più vile purché quello che ho fatto l'avessi voluto.", Author = "Cesare Pavese" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Cesare_Pavese", Text = "Mendicare o regnare, che importa? Abbiamo entrambi vissuto. Lascia il resto agli dèi.", Author = "Cesare Pavese" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Cesare_Pavese", Text = "Tutti avete una rupe, voi uomini. Per questo vi amavo. Ma gli dèi sono quelli che non sanno la rupe. Non sanno ridere né piangere.", Author = "Cesare Pavese" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Cesare_Pavese", Text = "Ma ricòrdati sempre che i mostri non muoiono. Quello che muore è la paura che t'incutono.", Author = "Cesare Pavese" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Cesare_Pavese", Text = "Io cercavo, piangendo, non più lei ma me stesso. Un destino, se vuoi. Mi ascoltavo.", Author = "Cesare Pavese" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Cesare_Pavese", Text = "Ho cercato me stesso. Non si cerca che questo.", Author = "Cesare Pavese" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Cesare_Pavese", Text = "Visto dal lato della vita tutto è bello. Ma credi a chi è stato tra i morti... Non vale la pena.", Author = "Cesare Pavese" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Cesare_Pavese", Text = "È necessario che ciascuno scenda una volta nel suo inferno. L'origine del mio destino è finita nell'Ade, finita cantando secondo i miei modi la vita e la morte.", Author = "Cesare Pavese" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Cesare_Pavese", Text = "Vuol dire che è dentro di te, cosa tua; più profondo del sangue, di là da ogni ebbrezza.", Author = "Cesare Pavese" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Cesare_Pavese", Text = "Non conosci la strada del sangue. Gli dèi non ti aggiungono né tolgono nulla. Solamente, d'un tocco leggero, t'inchiodano dove sei giunto.", Author = "Cesare Pavese" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Cesare_Pavese", Text = "Non c'è dei sopra il campo. C'è soltanto la terra, la Madre, la Grotta, che attende sempre e si riscuote soltanto sotto il fiotto di sangue.", Author = "Cesare Pavese" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Cesare_Pavese", Text = "Se una volta bastava un falò per far piovere, bruciarci sopra un vagabondo per salvare un raccolto, quante case di padroni bisogna incendiare, quanti ammazzarne per le strade e per le piazze, prima che il mondo torni giusto e noi si possa dir la nostra?", Author = "Cesare Pavese" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Cesare_Pavese", Text = "Sono ingiusti, gli dèi. Che bisogno hanno che si bruci gente viva?", Author = "Cesare Pavese" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Cesare_Pavese", Text = "Immortale è chi accetta l'istante. Chi non conosce più un domani.", Author = "Cesare Pavese" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Cesare_Pavese", Text = "Chi non spera di vivere.", Author = "Cesare Pavese" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Cesare_Pavese", Text = "Non c'è vero silenzio se non condiviso.", Author = "Cesare Pavese" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Cesare_Pavese", Text = "Non vale la pena, Odisseo. Chi non si ferma adesso, subito, non si ferma mai più.", Author = "Cesare Pavese" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Cesare_Pavese", Text = "Che cos'è vita eterna se non questo accettare l'istante che viene e l'istante che va?", Author = "Cesare Pavese" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Cesare_Pavese", Text = "È felice il ragazzo che fui, quello che è morto. Tu l'hai salvato, e ti ringrazio.", Author = "Cesare Pavese" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Cesare_Pavese", Text = "Ma ho bisogno di stringere a me un sangue caldo e fraterno. Ho bisogno di avere una voce e un destino.", Author = "Cesare Pavese" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Cesare_Pavese", Text = "Non importa, signora. Troppe volte mi sono specchiato nel lago. Chiedo di vivere, non di essere felice.", Author = "Cesare Pavese" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Cesare_Pavese", Text = "Sì. Qualcuno di loro sa ridere davanti al destino, sa ridere dopo, ma durante bisogna che faccia sul serio o che muoia.", Author = "Cesare Pavese" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Cesare_Pavese", Text = "L'uomo mortale, Leucò, non ha che questo d'immortale. Il ricordo che porta e il ricordo che lascia.", Author = "Cesare Pavese" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Cesare_Pavese", Text = "Ci fu un tempo che l'Ida non conobbe che dee. Che una dea. Era il sole, era i tronchi, era il mare.", Author = "Cesare Pavese" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Cesare_Pavese", Text = "C'è una verginità nelle cose, Mélita, che fa paura più del rischio. Pensa all'orrore delle vette dei monti, pensa all'eco.", Author = "Cesare Pavese" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Cesare_Pavese", Text = "Cara mia, ma gli dei sono il luogo, sono la solitudine, sono il tempo che passa.", Author = "Cesare Pavese" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Cesare_Pavese", Text = "Ogni cosa divina è crudele. Distrugge l'essere caduco che resiste.", Author = "Cesare Pavese" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Cesare_Pavese", Text = "Ma tu sai cosa sono gli uomini? Miserabili cose che dovranno morire, più miserabili dei vermi o delle foglie dell'altr'anno che son morti ignorandolo.", Author = "Cesare Pavese" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Cesare_Pavese", Text = "Sono invece scaduti i signori del Caos, quelli che un tempo hanno regnato senza legge.", Author = "Cesare Pavese" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Cesare_Pavese", Text = "La parola dell'uomo, che sa di patire e si affanna e possiede la terra, rivela a chi l'ascolta meraviglie.", Author = "Cesare Pavese" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Cesare_Pavese", Text = "Non sarebbero uomini, se non fossero tristi. La loro vita deve pur morire.", Author = "Cesare Pavese" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Cesare_Pavese", Text = "C'è un solo modo, e tu lo sai. [...] Dare un senso a quel loro morire.", Author = "Cesare Pavese" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Cesare_Pavese", Text = "Moriranno e avran vinta la morte. Vedranno qualcosa oltre il sangue, vedranno noi due.", Author = "Cesare Pavese" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Cesare_Pavese", Text = "Alle volte, non so. Mi chiedo che cosa sarebbe morire. Quest'è l'unica cosa che davvero ci manca.", Author = "Cesare Pavese" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Cesare_Pavese", Text = "Ma morire è proprio questo – non più sapere che sei morta. Ed è questo il diluvio: morire in tanti che non resti più nessuno a saperlo.", Author = "Cesare Pavese" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Cesare_Pavese", Text = "Strana gente. Loro trattano il destino e l'avvenire, come fosse un passato.", Author = "Cesare Pavese" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Cesare_Pavese", Text = "E carne e sangue gronderanno, non più per placare la morte, ma per raggiungere l'eterno che li aspetta.", Author = "Cesare Pavese" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Cesare_Pavese", Text = "La gioia di riavere una porta da chiudere e aprire, degli oggetti da riordinare – che era tutta la gioia della sua libertà – gli era durata a lungo, come una umile convalescenza.", Author = "Cesare Pavese" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Cesare_Pavese", Text = "Nessuno si fa casa di una cella, e Stefano si sentiva sempre intorno le pareti invisibili.", Author = "Cesare Pavese" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Cesare_Pavese", Text = "l'angoscia vera è fatta di noia, [...].", Author = "Cesare Pavese" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Cesare_Pavese", Text = "si resiste a star soli finché qualcuno soffre di non averci con sé, mentre la vera solitudine è una cella intollerabile.", Author = "Cesare Pavese" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Cesare_Pavese", Text = "Pensavo, invece, rientrando la sera, ai discorsi che avevo fatto con tutti ma a nessuno avevo detto ch'ero solo come un cane, e non mica perché non ci fosse più Amelio – anche lui mi mancava per questo.", Author = "Cesare Pavese" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Cesare_Pavese", Text = "Quando arrivai a Roma sul camion che Milo mi aveva trovato ero contento di aver fatto tanta strada e che al mondo ci fossero degli altri paesi, delle città, delle montagne, tanti posti che non avevo mai visto.", Author = "Cesare Pavese" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Cesare_Pavese", Text = "Il suo fianco era il mio. La sua voce era come abbracciarla.", Author = "Cesare Pavese" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Cesare_Pavese", Text = "L'acqua correva piano piano sotto il cielo.", Author = "Cesare Pavese" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Cesare_Pavese", Text = "Sei sì o no persuaso che lo stato dell'uomo è la debolezza? Come puoi sollevarti se prima non precipiti?", Author = "Cesare Pavese" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Cesare_Pavese", Text = "Non c'è niente che sappia di morte più del sole in estate della gran luce, della natura esuberante.", Author = "Cesare Pavese" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Cesare_Pavese", Text = "Tutto vive e si macera in se stesso. La natura è la morte.", Author = "Cesare Pavese" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Cesare_Pavese", Text = "Pensai a quanti luoghi ci sono nel mondo che appartengono così a qualcuno, che qualcuno ha nel sangue e nessun altro li sa.", Author = "Cesare Pavese" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Cesare_Pavese", Text = "Non sai che quello che ti tocca una volta si ripete? Che come si è reagito una volta, si reagisce sempre? Non è mica per caso che ti metti nei guai. Poi ci ricaschi.", Author = "Cesare Pavese" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Cesare_Pavese", Text = "Queste notti moderne, – disse Pieretto. – Sono vecchie come il mondo.", Author = "Cesare Pavese" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Cesare_Pavese", Text = "Una donna innamorata è sempre stupida.", Author = "Cesare Pavese" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Cesare_Pavese", Text = "La vita senza fumo è come il fumo senza l'arrosto.", Author = "Cesare Pavese" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Cesare_Pavese", Text = "Quale mondo giaccia di là di questo mare non so, ma ogni mare ha l'altra riva, e arriverò.", Author = "Cesare Pavese" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Cesare_Pavese", Text = "Il futuro verrà da un lungo dolore e un lungo silenzio.", Author = "Cesare Pavese" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Cesare_Pavese", Text = "Bisogna osservare bene questo: ai nostri tempi il suicidio è un modo di sparire, viene commesso timidamente, silenziosamente, schiacciatamente.", Author = "Cesare Pavese" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Cesare_Pavese", Text = "Non è più un agire, è un patire.", Author = "Cesare Pavese" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Cesare_Pavese", Text = "L'unico modo di sfuggire all'abisso è di guardarlo e misurarlo e sondarlo e discendervi.", Author = "Cesare Pavese" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Cesare_Pavese", Text = "Una donna che non sia stupida, presto o tardi, incontra un rottame umano e si prova a salvarlo.", Author = "Cesare Pavese" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Cesare_Pavese", Text = "Ma una donna che non sia una stupida, presto o tardi trova un uomo sano e lo riduce a rottame.", Author = "Cesare Pavese" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Cesare_Pavese", Text = "Le uniche donne che vale la pena di sposare, sono quelle che non ci si può fidare a sposare.", Author = "Cesare Pavese" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Cesare_Pavese", Text = "Un uomo non rimpiange per amore chi l'abbia tradito, ma per avvilimento di non avere meritato la fiducia.", Author = "Cesare Pavese" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Cesare_Pavese", Text = "Far poesie è come far l'amore: non si saprà mai se la propria gioia è condivisa.", Author = "Cesare Pavese" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Cesare_Pavese", Text = "Se è vero che ci si abitua al dolore, come mai con l'andar degli anni si soffre sempre di più?", Author = "Cesare Pavese" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Cesare_Pavese", Text = "No, non sono pazzi questa gente che si diverte, che gode, che viaggia, che fotte, che combatte – non sono pazzi, tanto è vero che vorremmo farlo anche noi.", Author = "Cesare Pavese" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Cesare_Pavese", Text = "L'unica gioia al mondo è cominciare.", Author = "Cesare Pavese" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Cesare_Pavese", Text = "È bello vivere perché vivere è cominciare, sempre, ad ogni istante.", Author = "Cesare Pavese" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Cesare_Pavese", Text = "Ma la grande, la tremenda verità è questa: soffrire non serve a niente.", Author = "Cesare Pavese" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Cesare_Pavese", Text = "Pensiero d'amore: ti voglio tanto bene che desidero esser nato tuo fratello, o averti messo al mondo io stesso.", Author = "Cesare Pavese" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Cesare_Pavese", Text = "Ogni critico è propriamente una donna nell'età critica, astioso e refoulé.", Author = "Cesare Pavese" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Cesare_Pavese", Text = "Proprio a te doveva accadere di concentrare tutta la vita su un punto, e poi scoprire che tutto puoi fare tranne vivere quel punto.", Author = "Cesare Pavese" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Cesare_Pavese", Text = "Se il chiavare non fosse la cosa più importante della vita, la Genesi non comincerebbe di lì.", Author = "Cesare Pavese" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Cesare_Pavese", Text = "C'è qualcosa di più triste che invecchiare, ed è rimanere bambini.", Author = "Cesare Pavese" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Cesare_Pavese", Text = "Questo è definitivo: tutto potrai avere dalla vita, meno che una donna ti chiami il suo uomo.", Author = "Cesare Pavese" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Cesare_Pavese", Text = "L'arte di vivere è l'arte di saper credere alle menzogne.", Author = "Cesare Pavese" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Cesare_Pavese", Text = "Povera gente, i testicoli da cui siamo nati, sono ancora sempre la nostra sostanza.", Author = "Cesare Pavese" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Cesare_Pavese", Text = "La difficoltà di commettere suicidio sta in questo: è un atto d'ambizione che si può commettere solo quando si sia superata ogni ambizione.", Author = "Cesare Pavese" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Cesare_Pavese", Text = "Perché il veramente innamorato chiede la continuità, la vitalità (lifelongness) dei rapporti?", Author = "Cesare Pavese" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Cesare_Pavese", Text = "Consolante pensiero: non contano le azioni che facciamo, ma l'animo con cui le facciamo.", Author = "Cesare Pavese" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Cesare_Pavese", Text = "Per disprezzare il denaro bisogna appunto averne, e molto.", Author = "Cesare Pavese" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Cesare_Pavese", Text = "Quei filosofi che credono all'assoluto logico della verità, non hanno mai avuto a che discorrere a ferri corti con una donna.", Author = "Cesare Pavese" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Cesare_Pavese", Text = "Vendicarsi di un torto ricevuto è togliersi il conforto di gridare all'ingiustizia.", Author = "Cesare Pavese" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Cesare_Pavese", Text = "Non manca mai a nessuno una buona ragione per uccidersi.", Author = "Cesare Pavese" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Cesare_Pavese", Text = "Perché – quando si è sbagliato – si dice «un'altra volta saprò come fare», quando si dovrebbe dire «un'altra volta so già come farò»?", Author = "Cesare Pavese" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Cesare_Pavese", Text = "Siccome Dio poteva creare una libertà che non consentisse il male (cfr. lo stato dei beati liberi e certi di non peccare), ne viene che il male l'ha voluto lui.", Author = "Cesare Pavese" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Cesare_Pavese", Text = "In fondo, l'unica ragione perché si pensa sempre al proprio io è che col nostro io dobbiamo stare più continuamente che non chiunque altro.", Author = "Cesare Pavese" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Cesare_Pavese", Text = "La morte è il riposo, ma il pensiero della morte è il disturbatore di ogni riposo.", Author = "Cesare Pavese" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Cesare_Pavese", Text = "Tutti «gli affetti più sacri» non sono che una pigra abitudine.", Author = "Cesare Pavese" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Cesare_Pavese", Text = "Tanto poco un uomo s'interessa dell'altro, che persino il cristianesimo raccomanda di fare il bene per amore di Dio.", Author = "Cesare Pavese" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Cesare_Pavese", Text = "Il fascino sottile delle convalescenze consiste in questo: tornare alle proprie abitudini con l'illusione di scoprirle.", Author = "Cesare Pavese" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Cesare_Pavese", Text = "Gli uomini che hanno una tempestosa vita interiore e non cercano sfogo o nei discorsi o nella scrittura, sono semplicemente uomini che non hanno una tempestosa vita interiore.", Author = "Cesare Pavese" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Cesare_Pavese", Text = "Date una compagnia al solitario e parlerà più di chiunque.", Author = "Cesare Pavese" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Cesare_Pavese", Text = "L'origine di tutti i peccati è il senso d'inferiorità – detto altresì ambizione.", Author = "Cesare Pavese" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Cesare_Pavese", Text = "L'uomo d'azione non è l'ignorante che si butta allo sbaraglio dimenticandosi, ma l'uomo che ritrova nella pratica le cose che sa.", Author = "Cesare Pavese" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Cesare_Pavese", Text = "L'offesa più atroce che si può fare a un uomo è negargli che soffra.", Author = "Cesare Pavese" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Cesare_Pavese", Text = "Sciocco addolorarsi per la perdita di una compagnia: quella persona potevamo non incontrarla mai, quindi possiamo farne a meno.", Author = "Cesare Pavese" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Cesare_Pavese", Text = "La religione consiste nel credere che tutto quello che ci accade è straordinariamente importante.", Author = "Cesare Pavese" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Cesare_Pavese", Text = "Non si desidera di godere. Si desidera sperimentare la vanità di un piacere, per non esserne più ossessionati.", Author = "Cesare Pavese" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Cesare_Pavese", Text = "La fantasia umana è immensamente più povera della realtà.", Author = "Cesare Pavese" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Cesare_Pavese", Text = "Soffrire non serve a niente | Soffrire limita l'efficienza spirituale | Soffrire è sempre colpa nostra | Soffrire è una debolezza.", Author = "Cesare Pavese" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Cesare_Pavese", Text = "Non bastano le disgrazie a fare di un fesso una persona intelligente.", Author = "Cesare Pavese" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Cesare_Pavese", Text = "Sostenere che i nostri successi ci sono impartiti dalla Provvidenza e non dall'astuzia, è un'astuzia di più per aumentare ai nostri occhi l'importanza di questi successi.", Author = "Cesare Pavese" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Cesare_Pavese", Text = "Passavo la sera seduto davanti allo specchio per tenermi compagnia...", Author = "Cesare Pavese" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Cesare_Pavese", Text = "La letteratura è una difesa contro le offese della vita.", Author = "Cesare Pavese" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Cesare_Pavese", Text = "Non si desidera possedere una donna, si desidera possederla noi soli.", Author = "Cesare Pavese" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Cesare_Pavese", Text = "Leggendo non cerchiamo idee nuove, ma pensieri già da noi pensati, che acquistano sulla pagina un suggello di conferma.", Author = "Cesare Pavese" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Cesare_Pavese", Text = "L'ozio rende lente le ore e veloci gli anni. L'operosità rapide le ore e lenti gli anni.", Author = "Cesare Pavese" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Cesare_Pavese", Text = "La cosa più banale, scoperta in noi diventa interessantissima.", Author = "Cesare Pavese" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Cesare_Pavese", Text = "Per libertario che sia un giovane, cerca sempre di modellarsi su di uno schema astratto, quale in sostanza deduce dall'esempio del mondo.", Author = "Cesare Pavese" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Cesare_Pavese", Text = "Tutto il problema della vita è dunque questo: come rompere la propria solitudine, come comunicare con altri.", Author = "Cesare Pavese" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Cesare_Pavese", Text = "Il sesso è un incidente: ciò che ne riceviamo è momentaneo e casuale; noi miriamo a qualcosa di più riposto e misterioso di cui il sesso è solo un segno, un simbolo.", Author = "Cesare Pavese" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Cesare_Pavese", Text = "La politica è l'arte del possibile. Tutta la vita è politica.", Author = "Cesare Pavese" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Cesare_Pavese", Text = "La guerra imbarbarisce perché, per combatterla, occorre indurirsi verso ogni rimpianto e attaccamento a valori delicati.", Author = "Cesare Pavese" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Cesare_Pavese", Text = "Si fa l'elemosina, per levarsi d'innanzi il miserabile che la chiede.", Author = "Cesare Pavese" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Cesare_Pavese", Text = "Ci vuole la ricchezza d'esperienze del realismo e la profondità di sensi del simbolismo.", Author = "Cesare Pavese" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Cesare_Pavese", Text = "Tutta l'arte è un problema di equilibrio fra due opposti.", Author = "Cesare Pavese" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Cesare_Pavese", Text = "L'amore è la più a buon prezzo delle religioni.", Author = "Cesare Pavese" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Cesare_Pavese", Text = "Le cose gratuite sono quelle che costano di più.", Author = "Cesare Pavese" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Cesare_Pavese", Text = "In genere è per mestiere disposto a sacrificarsi chi non sa altrimenti dare un senso alla sua vita.", Author = "Cesare Pavese" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Cesare_Pavese", Text = "Se una vita libera assolutamente da ogni senso di peccato fosse realizzabile, sarebbe vuota da far spavento.", Author = "Cesare Pavese" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Cesare_Pavese", Text = "Le generazioni non invecchiano. Ogni giovane di qualunque tempo e civiltà ha le stesse possibilità di sempre.", Author = "Cesare Pavese" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Cesare_Pavese", Text = "Finché si avranno passioni non si cesserà di scoprire il mondo.", Author = "Cesare Pavese" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Cesare_Pavese", Text = "Il sogno è una costruzione dell'intelligenza, cui il costruttore assiste senza sapere come andrà a finire.", Author = "Cesare Pavese" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Cesare_Pavese", Text = "Gli anacoreti si maltrattavano a quel modo, per farsi scusare presso la gente comune la beatitudine che avrebbero goduto in cielo.", Author = "Cesare Pavese" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Cesare_Pavese", Text = "Non si ricordano i giorni, si ricordano gli attimi.", Author = "Cesare Pavese" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Cesare_Pavese", Text = "Non bisogna mai dire per gioco che si è scoraggiati, perché può accadere che ci pigliamo in parola.", Author = "Cesare Pavese" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Cesare_Pavese", Text = "La vita non è ricerca di esperienze, ma di se stessi.", Author = "Cesare Pavese" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Cesare_Pavese", Text = "Riesce a compiere un'opera soltanto chi valga più di quest'opera.", Author = "Cesare Pavese" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Cesare_Pavese", Text = "La vera genialità [...] non è conquistare una donna già desiderata da tutti, ma scovarne una preziosa in un essere ignorato.", Author = "Cesare Pavese" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Cesare_Pavese", Text = "C'è un'arte di ricevere in faccia le sferzate del dolore, che bisogna imparare.", Author = "Cesare Pavese" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Cesare_Pavese", Text = "L'amore ha la virtù di denudare non i due amanti l'uno di fronte all'altro, ma ciascuno dei due davanti a sé.", Author = "Cesare Pavese" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Cesare_Pavese", Text = "I grandi amanti saranno sempre infelici, perché per loro l'amore è grande e quindi esigono dalla bienaimée la stessa intensità di pensieri ch'essi hanno per lei – altrimenti si sentono traditi.", Author = "Cesare Pavese" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Cesare_Pavese", Text = "Le cose si ottengono quando non si desiderano più.", Author = "Cesare Pavese" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Cesare_Pavese", Text = "Una decisione, un atto, sono infallibili presagi di ciò che faremo un'altra volta, non per qualche mistica ragione astrologica, ma perché escono da un automatismo che si riprodurrà.", Author = "Cesare Pavese" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Cesare_Pavese", Text = "Nessuna donna fa un matrimonio d'interesse: tutte hanno l'accortezza, prima di sposare un milionario, d'innamorarsene.", Author = "Cesare Pavese" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Cesare_Pavese", Text = "Quando una donna si sposa appartiene a un altro; e quando appartiene a un altro non c'è più nulla da dirle.", Author = "Cesare Pavese" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Cesare_Pavese", Text = "Le cose si scoprono attraverso i ricordi che se ne hanno.", Author = "Cesare Pavese" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Cesare_Pavese", Text = "Ricordare una cosa significa vederla – ora soltanto – per la prima volta.", Author = "Cesare Pavese" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Cesare_Pavese", Text = "Nell'inquietudine e nello sforzo di scrivere, ciò che sostiene è la certezza che nella pagina resta qualcosa di non detto.", Author = "Cesare Pavese" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Cesare_Pavese", Text = "Amore è desiderio di conoscenza.", Author = "Cesare Pavese" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Cesare_Pavese", Text = "Viene un giorno che per chi ci ha perseguitato proviamo soltanto indifferenza, stanchezza della sua stupidità.", Author = "Cesare Pavese" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Cesare_Pavese", Text = "Il problema non è la durezza della sorte, poiché tutto quello che si desidera con bastante forza, si ottiene.", Author = "Cesare Pavese" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Cesare_Pavese", Text = "Il problema è piuttosto che ciò che si ottiene disgusta.", Author = "Cesare Pavese" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Cesare_Pavese", Text = "Nel sogno sei autore e non sai come finirà.", Author = "Cesare Pavese" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Cesare_Pavese", Text = "Raccontare le cose incredibili come fossero reali – sistema antico; raccontare le reali come fossero incredibili – moderno.", Author = "Cesare Pavese" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Cesare_Pavese", Text = "La tua modernità sta tutta nel senso dell'irrazionale.", Author = "Cesare Pavese" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Cesare_Pavese", Text = "La ricchezza della vita è fatta di ricordi, dimenticati.", Author = "Cesare Pavese" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Cesare_Pavese", Text = "L'innamorato e l'odiatore si fanno dei simboli, come il superstizioso.", Author = "Cesare Pavese" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Cesare_Pavese", Text = "E vertendo sul primitivo gode del selvaggio. Cioè dell'irrazionale (sangue e sesso).", Author = "Cesare Pavese" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Cesare_Pavese", Text = "Viene un'epoca in cui ci si rende conto che tutto ciò che facciamo diventerà a suo tempo ricordo.", Author = "Cesare Pavese" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Cesare_Pavese", Text = "Non è bello esser bambini: è bello da anziani pensare a quando eravamo bambini.", Author = "Cesare Pavese" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Cesare_Pavese", Text = "Non ci si libera di una cosa evitandola, ma soltanto attraversandola.", Author = "Cesare Pavese" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Cesare_Pavese", Text = "Certo, avere una donna che ti aspetta, che dormirà con te, è come il tepore di qualcosa che dovrai dire, e ti scalda e t'accompagna e ti fa vivere.", Author = "Cesare Pavese" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Cesare_Pavese", Text = "Non c'è vendetta più bella di quella che gli altri infliggono al tuo nemico.", Author = "Cesare Pavese" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Cesare_Pavese", Text = "È bello scrivere perché riunisce le due gioie: parlare da solo e parlare a una folla.", Author = "Cesare Pavese" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Cesare_Pavese", Text = "Le lezioni non si dànno, si prendono.", Author = "Cesare Pavese" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Cesare_Pavese", Text = "Aspettare è ancora un'occupazione. È non aspettar niente che è terribile.", Author = "Cesare Pavese" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Cesare_Pavese", Text = "C'è un solo piacere, quello di essere vivi, tutto il resto è miseria.", Author = "Cesare Pavese" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Cesare_Pavese", Text = "Si aspira ad avere un lavoro, per avere il diritto di riposarsi.", Author = "Cesare Pavese" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Cesare_Pavese", Text = "I problemi che agitano una generazione si estinguono per la generazione successiva non perché siano stati risolti ma perché il disinteresse generale li abolisce.", Author = "Cesare Pavese" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Cesare_Pavese", Text = "Il mito greco insegna che si combatte sempre contro una parte di sé, quella che si è superata, Zeus contro Tifone, Apollo contro il Pitone.", Author = "Cesare Pavese" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Cesare_Pavese", Text = "Non è che accadano a ciascuno cose secondo un destino, ma le cose accadute ciascuno le interpreta, se ne ha la forza, disponendole secondo un senso – vale a dire, un destino.", Author = "Cesare Pavese" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Cesare_Pavese", Text = "Si odiano gli altri, perché si odia se stessi.", Author = "Cesare Pavese" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Cesare_Pavese", Text = "Perché il mondo l'avvenire ora l'hai dentro come passato, come esperienza, come tecnica, e il perenne e ricco mistero si ritrova essere quel tu infantile che non hai fatto in tempo a possedere.", Author = "Cesare Pavese" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Cesare_Pavese", Text = "Tutte le passioni passano e si spengono tranne le più antiche, quelle dell'infanzia.", Author = "Cesare Pavese" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Cesare_Pavese", Text = "Non ci si uccide per amore di una donna. Ci si uccide perché un amore, qualunque amore, ci rivela nella nostra nudità, miseria, inermità, nulla.", Author = "Cesare Pavese" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Cesare_Pavese", Text = "Il gesto – il gesto – non dev'essere una vendetta. Dev'essere una calma e stanca rinuncia, una chiusa di conti, un fatto privato e ritmico.", Author = "Cesare Pavese" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Cesare_Pavese", Text = "Nulla si assomma al resto, al passato. Ricominciamo sempre.", Author = "Cesare Pavese" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Cesare_Pavese", Text = "Chiodo scaccia chiodo. Ma quattro chiodi fanno una croce.", Author = "Cesare Pavese" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Cesare_Pavese", Text = "I suicidi sono omicidi timidi. Masochismo invece che sadismo.", Author = "Cesare Pavese" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Cesare_Pavese", Text = "Pieretto diceva che la vecchia pretesa di trovare intatta la donna era un residuo dello stesso gusto – la sciocca mania di arrivare primo.", Author = "Cesare Pavese" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Cesare_Pavese", Text = "Si fa all'amore per ferire, per spargere sangue.", Author = "Cesare Pavese" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Cesare_Pavese", Text = "È bello svegliarsi e non farsi illusioni. Ci si sente liberi e responsabili.", Author = "Cesare Pavese" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Cesare_Pavese", Text = "I lavativi hanno la pelle dura.", Author = "Cesare Pavese" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Cesare_Pavese", Text = "La vera confidenza è sapere quel che desidera un altro, e quando piacciono le stesse cose una persona non dà più soggezione.", Author = "Cesare Pavese" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Cesare_Pavese", Text = "Un padre va sempre aiutato. Bisogna insegnargli che la vita è difficile.", Author = "Cesare Pavese" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Cesare_Pavese", Text = "Non avevo tristezze, sapevo che nella notte la città poteva andare tutta in fiamme e la gente morire.", Author = "Cesare Pavese" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Cesare_Pavese", Text = "Con la guerra divenne legittimo chiudersi in sé, vivere alla giornata, non rimpiangere piú le occasioni perdute.", Author = "Cesare Pavese" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Cesare_Pavese", Text = "Quella specie di sordo rancore in cui s’era conchiusa la mia gioventú, trovò con la guerra una tana e un orizzonte.", Author = "Cesare Pavese" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Cesare_Pavese", Text = "Dietro ai coltivi e alle strade, dietro alle case umane, sotto i piedi, l'antico indifferente cuore della terra covava nel buio, viveva in burroni, in radici, in cose occulte, in paure d'infanzia.", Author = "Cesare Pavese" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Cesare_Pavese", Text = "Si direbbe che sotto ai rancori e alle incertezze, sotto alla voglia di star solo, mi scoprivo ragazzo per avere un compagno, un collega, un figliolo.", Author = "Cesare Pavese" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Cesare_Pavese", Text = "Ci si poteva abbandonare e poi riprendere; nulla accadeva e tutto aveva sapore.", Author = "Cesare Pavese" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Cesare_Pavese", Text = "Se non lo fossimo, dovremmo rivoltarci, tirare le bombe, rischiare la pelle. Chi lascia fare e s’accontenta, è già un fascista.", Author = "Cesare Pavese" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Cesare_Pavese", Text = "Si passano insieme dei mesi, degli anni, poi succede. Si perde un appuntamento, si cambia casa, e uno che vedevi tutti i giorni non sai nemmeno piú chi sia.", Author = "Cesare Pavese" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Cesare_Pavese", Text = "Il coraggio di starsene soli come se gli altri non ci fossero e pensare soltanto alla cosa che fai.", Author = "Cesare Pavese" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Cesare_Pavese", Text = "Inutile piangere. Si nasce e si muore da soli...", Author = "Cesare Pavese" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Cesare_Pavese", Text = "Quella guerra in cui vivevo rifugiato, convinto di averla accettata, di essermene fatta una pace scontrosa, inferociva, mordeva piú a fondo, giungeva ai nervi e nel cervello.", Author = "Cesare Pavese" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Cesare_Pavese", Text = "Nelle parole c'è qualcosa d'impudico.", Author = "Cesare Pavese" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Cesare_Pavese", Text = "Conta quello che si fa, non che si dice.", Author = "Cesare Pavese" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Cesare_Pavese", Text = "È religione anche non credere in niente.", Author = "Cesare Pavese" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Cesare_Pavese", Text = "Oggi ancora mi chiedo perché quei tedeschi non mi aspettarono alla villa mandando qualcuno a cercarmi a Torino.", Author = "Cesare Pavese" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Cesare_Pavese", Text = "Perch'ero entrato quella volta in chiesa? L'esperienza del pericolo rende vigliacchi ogni giorno di piú.", Author = "Cesare Pavese" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Cesare_Pavese", Text = "A volte, dopo avere ascoltato l'inutile radio, guardando dal vetro le vigne deserte penso che vivere per caso non è vivere.", Author = "Cesare Pavese" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Cesare_Pavese", Text = "Ma ho visto i morti sconosciuti, i morti repubblichini. Sono questi che mi hanno svegliato.", Author = "Cesare Pavese" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Cesare_Pavese", Text = "Se un ignoto, un nemico, diventa morendo una cosa simile, se ci si arresta e si ha paura a scavalcarlo, vuol dire che anche vinto il nemico è qualcuno.", Author = "Cesare Pavese" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Cesare_Pavese", Text = "Guardare certi morti è umiliante. Non sono piú faccenda altrui; non ci si sente capitati sul posto per caso.", Author = "Cesare Pavese" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Cesare_Pavese", Text = "Per questo ogni guerra è una guerra civile: ogni caduto somiglia a chi resta, e gliene chiede ragione.", Author = "Cesare Pavese" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Cesare_Pavese", Text = "Perché questo è l'ostacolo, la crosta da rompere: la solitudine dell'uomo – di noi e degli altri.", Author = "Cesare Pavese" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Cesare_Pavese", Text = "La vita di ogni artista e di ogni uomo è come quella dei popoli un incessante sforzo per ridurre a chiarezza i suoi miti.", Author = "Cesare Pavese" },
        };
    }
}